function audioUI(){const running=sound.ready&&sound.enabled;$('#soundToggle').textContent=running?'♫ بی‌صدا کردن':sound.enabled?'♫ فعال‌کردن صدا':'♫ صدا خاموش';$('#screenSoundButton').textContent=running?'♫ صدا روشن':'♫ فعال‌کردن صدا';$('#screenSoundButton').setAttribute('aria-label',running?'بی‌صدا کردن':'فعال‌کردن صدا');$('#screenSoundButton').classList.toggle('ready',running);$('#audioStatus').textContent=running?'فعال':sound.enabled?'منتظر کلیک':'بی‌صدا';$('#soundVolume').value=Math.round(sound.volume*100);$('#ambientSound').checked=game.s.audio?.musicEnabled===true;}
function syncAudio(){const sharedVolume=game.s.audio?.volume??.32;if(sound.volume!==sharedVolume)sound.setVolume(sharedVolume);if(sound.ambient!==(game.s.audio?.musicEnabled===true))sound.setAmbient(game.s.audio?.musicEnabled===true);const s=game.s,id=currentParticipant(),key=id?`${s.round}:${id}`:'';if(key&&key!==lastAudibleTurn&&sound.ready&&sound.enabled){sound.turn();lastAudibleTurn=key}if(!hosted&&previousTurn?.startsWith(`${s.round}:`)&&previousTurn!==key&&s.mode==='tie'&&!s.active&&s.phase==='playing')setTimeout(()=>shuffleAnimation(),550);previousTurn=key;if(s.phase==='lobby'){lastAudibleTurn='';lastWinSound=''}if(s.phase==='won'&&experience==='game'){const k=`${s.round}:${s.winner}`;if(k!==lastWinSound&&sound.ready&&sound.enabled){sound.win();lastWinSound=k}}sound.setQuiet(!s.active&&!s.manualReveal&&Date.now()>=focusUntil&&Date.now()>=shuffleUntil);audioUI();}
