function profileRankings(r){return [...(r?.members||[])].filter(p=>p.points>0).sort((a,b)=>b.points-a.points||b.coins-a.coins||a.lastActivityAt-b.lastActivityAt).slice(0,3);}
function profileAwards(r){return r?.categoryLeaders||Object.fromEntries(['coins','likes','comments'].map(k=>[k,[...(r?.members||[])].filter(p=>p[k]>0).sort((a,b)=>b[k]-a[k]||b.points-a.points||a.lastActivityAt-b.lastActivityAt)[0]?.id||'']));}
function profileCrown(){const n=el('span','podium-crown');n.innerHTML='<svg viewBox="0 0 100 62" aria-label="Golden crown"><defs><linearGradient id="crownGold" x2="0" y2="1"><stop stop-color="#fff5b1"/><stop offset=".4" stop-color="#f3c44f"/><stop offset=".7" stop-color="#aa6417"/><stop offset="1" stop-color="#ffe89d"/></linearGradient></defs><path fill="url(#crownGold)" stroke="#ffe5a0" stroke-width="2" d="M10 18L29 35L36 12L50 30L64 12L71 35L90 18L82 51Q50 62 18 51Z"/><path d="M18 45Q50 56 82 45M22 51Q50 60 78 51" fill="none" stroke="#fff3ad" stroke-width="3"/><g fill="#fff0a3" stroke="#c98b27"><circle cx="10" cy="16" r="5"/><circle cx="36" cy="10" r="5"/><circle cx="64" cy="10" r="5"/><circle cx="90" cy="16" r="5"/></g><path fill="#6be6ff" stroke="#f9e2a0" d="M50 35L56 43L50 51L44 43Z"/><circle cx="29" cy="44" r="3" fill="#ff708c"/><circle cx="71" cy="44" r="3" fill="#ff708c"/></svg>';return n;}
function renderProfilePodium(grid,top,r){let stage=grid.querySelector('.profile-live-podium');if(!stage){stage=el('section','profile-live-podium');stage.setAttribute('aria-label','Round top three');grid.append(stage);}const key=JSON.stringify([r?.number,top.map(p=>[p.id,p.points,p.avatar,p.name,p.coins,p.likes,p.comments])]);if(stage.dataset.key===key)return;const before=new Map([...stage.querySelectorAll('[data-leader-id]')].map(n=>[n.dataset.leaderId,n.getBoundingClientRect()]));stage.dataset.key=key;stage.replaceChildren(el('span','podium-label','ROUND '+(r?.number||1)+' · TOP SUPPORTERS'));for(const rank of [2,1,3]){const p=top[rank-1],card=el('div','profile-podium-card place-'+rank+(p?'':' empty'));card.dataset.rank=rank;if(p)card.dataset.leaderId=p.id;card.append(el('span','podium-rank',String(rank)));if(rank===1)card.append(profileCrown());else card.append(el('span','podium-trophy',rank===2?'🏆':'🏆'),el('span','podium-medal',rank===2?'🥈':'🥉'));if(p){card.append(funPicture(p),el('strong','podium-name',p.name),el('b','podium-points',p.points+' PTS'));const metrics=el('small','podium-metrics','♦ '+p.coins+'  ♥ '+p.likes+'  ✉ '+p.comments);card.append(metrics);}else card.append(el('span','podium-wait','—'));stage.append(card);if(p&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const old=before.get(p.id);const next=card.getBoundingClientRect(),scale=grid.getBoundingClientRect().width/grid.offsetWidth;card.animate(old?[{transform:`translate(${(old.left-next.left)/scale}px,${(old.top-next.top)/scale}px)`,filter:'brightness(1.5)'},{transform:'none',filter:'brightness(1)'}]:[{opacity:0,transform:'rotateY(-50deg)'},{opacity:1,transform:'none'}],{duration:650,easing:'cubic-bezier(.2,.8,.3,1)'});}}}
function profileTime(ms){const n=Math.max(0,Math.ceil(ms/1000));return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');}
function profileBubbles(target,p,plan){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const level=p.level||0,gift=p.lastActivityKind==='gift',count=6+level*3+(gift?8:0),fx=gift?'gold':plan.effect,colour=gift?'#ffda70':'var(--profile-accent,#8de7ff)';target.dataset.fx=fx;const overlay=el('span','profile-fx-overlay fx-'+fx);overlay.style.setProperty('--fx-colour',colour);target.append(overlay);overlay.innerHTML='<i class="fx-streak"></i><i class="fx-streak second"></i><i class="fx-mist"></i><i class="fx-bolt"></i>';setTimeout(()=>{overlay.remove();if(target.dataset.fx===fx)delete target.dataset.fx;},plan.duration);for(let i=0;i<count;i++){const b=el('i','profile-spark particle-'+fx,gift?'✦':fx==='crown'?'♛':fx==='ice'||fx==='prism'?'◆':i%3===0?'✦':'');target.append(b);b.style.color=colour;b.style.left=(8+(i*37)%84)+'%';const seed=(i+1)*2.399963,distance=24+level*4+i%5*8,dx=Math.cos(seed)*distance,dy=Math.sin(seed)*distance-20,spin=(i%2?1:-1)*(90+i*17);const frames=fx==='wave'||fx==='aurora'||fx==='ribbon'?[{transform:'translate(0,15px) scale(.1)',opacity:0},{transform:`translate(${dx}px,-20px) scale(1)`,opacity:1,offset:.3},{transform:`translate(${-dx}px,${-70-i%4*10}px) scale(.2) rotate(${spin}deg)`,opacity:0}]:fx==='electric'?[{transform:'translate(0,10px)',opacity:0},{transform:`translate(${dx}px,${dy}px)`,opacity:1,offset:.15},{transform:`translate(${-dx*.5}px,${dy-10}px)`,opacity:.7,offset:.45},{transform:`translate(${dx*.8}px,${dy-40}px) scale(.1)`,opacity:0}]:[{transform:'translate(0,15px) scale(.1)',opacity:0},{transform:`translate(${dx*.4}px,${dy*.4}px) scale(1.2)`,opacity:1,offset:.2},{transform:`translate(${dx}px,${dy-50}px) rotate(${spin}deg) scale(.1)`,opacity:0}];const a=b.animate(frames,{duration:1400+i%5*260,delay:i%6*80,fill:'forwards',easing:'cubic-bezier(.15,.5,.3,1)'});a.finished.then(()=>b.remove(),()=>b.remove());}}

